            continue;
        if (checked[roomName])
            continue;
        checked[roomName] = true;
        // Skip our own rooms
        var isOurs = false;
        for (var ownedName in Game.rooms) {
            var ownedRoom = Game.rooms[ownedName];
            if (ownedRoom && ownedRoom.controller && ownedRoom.controller.my &&
                ownedName === roomName) {
