    if (!conquest) {
        initConquestState(campaign);
        conquest = campaign.controllerAttack.conquest;
    }
    var room = Game.rooms[campaign.targetRoom];
    if (!room)
        return; // No vision
    // Update structure counts
    var hostileStructures = room.find(FIND_STRUCTURES, {
        filter: function (s) {
            if (s.my)
                return false;
            if (s.structureType === STRUCTURE_CONTROLLER)
