    computeUpgraderTarget(colony) {
        const rcl = colony.rcl;
        const hasStorage = colony.hasStorage;
        // Early colonies: always at least 1 upgrader
        if (rcl <= 3 && !hasStorage) {
            // Infrastructure complete? Push RCL harder
            if (colony.milestones.hasFullExtensions) {
                return Math.min(rcl, 3);
            }
            return 1;
        }
        // RCL 8: cap at 1 (15/tick limit)
        if (rcl >= 8)
            return 1;
        // Scale with RCL
        return Math.min(rcl, 3);
    }
    computeBuilderTarget(colony) {
        const totalSites = colony.constructionSites.length;
        if (totalSites === 0)
            return 0;
        // Pioneer phase: pioneers build
        if (this.isPioneerPhase(colony))
            return 0;
        const rcl = colony.rcl;
        const hasStorage = colony.hasStorage;
        if (rcl <= 3 && !hasStorage) {
            // Early colony: 1-2 builders based on income
            const estimatedIncome = colony.sourceCount * 6;
            const maxBuildersForIncome = Math.floor((estimatedIncome * 0.5) / 2.5);
            return Math.min(2, Math.max(1, maxBuildersForIncome));
        }
        // RCL 4+: scale by site count
        const maxBuildersByEconomy = Math.min(rcl, 4);
        return Math.min(Math.ceil(totalSites / 10), maxBuildersByEconomy);
    }
    computeRemoteHaulerTarget(colony) {
        let total = 0;
        for (const remote of colony.remotes) {
            if (!remote.active || remote.paused)
                continue;
            // Distance-aware: more haulers for farther rooms
            total += remote.distance >= 2 ? 3 : 2;
        }
        return total;
    }
    computeRemoteBuilderTarget(colony) {
        // Only if remotes need containers
        let needsBuilder = false;
        for (const remote of colony.remotes) {
            if (remote.active && !remote.hasContainers) {
                needsBuilder = true;
                break;
            }
        }
        return needsBuilder ? 1 : 0;
    }
    needsScout(colony, state) {
        if (colony.rcl < 3)
            return false;
        // Check adjacent rooms for stale or missing intel
        const room = Game.rooms[colony.roomName];
        if (!room)
            return false;
        const exits = Game.map.describeExits(colony.roomName);
        if (!exits)
            return false;
        for (const dir in exits) {
            const adjRoom = exits[dir];
            if (!adjRoom)
                continue;
            const intel = state.intel.get(adjRoom);
            if (!intel || Game.time - intel.lastScanned > 5000) {
                return true;
            }
        }
        return false;
    }
    // ==========================================================================
    // FACTOR COMPUTATION
    // ==========================================================================
    isPioneerPhase(colony) {
        // Pioneer phase: RCL 1, no source containers, no storage
        if (colony.hasStorage)
            return false;
        if (colony.rcl >= 2)
            return false;
        return !colony.milestones.hasSourceContainers;
    }
    computeEconomyHealth(colony) {
        if (colony.harvestIncome === 0)
            return 0.3; // Dead economy
        if (colony.netFlow >= 0)
            return 1.0; // Positive flow = healthy
        // Negative flow: scale down
        return Math.max(0.2, 1 + colony.netFlow / colony.harvestIncome);
    }
    computeRoleSpecificFactor(role, colony, state, factors) {
        switch (role) {
            case "HARVESTER": {
                // Boost when income is critically low
                if (colony.harvestIncome < colony.maxHarvestIncome * 0.3) {
                    const scarcityBoost = 1.5;
                    this.addFactor(factors, "incomeScarcity", colony.harvestIncome, 1.0, scarcityBoost - 1);
                    return scarcityBoost;
                }
                return 1.0;
            }
            case "HAULER": {
                // Boost when no haulers exist but harvesters do
                const harvesterCount = colony.counts["HARVESTER"] || 0;
                const haulerCount = colony.counts["HAULER"] || 0;
                if (harvesterCount > 0 && haulerCount === 0 && colony.harvestIncome > 0) {
                    const criticalBoost = 1.5;
                    this.addFactor(factors, "noHaulers", 1, 1.0, criticalBoost - 1);
                    return criticalBoost;
                }
                return 1.0;
            }
            case "UPGRADER": {
                // First upgrader in early colony is critical
                const upgraderCount = colony.counts["UPGRADER"] || 0;
                if (colony.rcl <= 3 && !colony.hasStorage && upgraderCount === 0) {
                    const firstUpgraderBoost = 1.5;
                    this.addFactor(factors, "firstUpgrader", 1, 1.0, firstUpgraderBoost - 1);
                    return firstUpgraderBoost;
                }
                return 1.0;
            }
            case "BUILDER": {
                // Boost for first builder when sites exist
                const builderCount = colony.counts["BUILDER"] || 0;
                if (builderCount === 0 && colony.constructionSites.length > 0) {
                    const firstBuilderBoost = 1.3;
                    this.addFactor(factors, "firstBuilder", 1, 1.0, firstBuilderBoost - 1);
                    return firstBuilderBoost;
                }
                return 1.0;
            }
            case "REMOTE_MINER":
            case "REMOTE_HAULER": {
                // Gate on home economy stability
                const harvesterCount = colony.counts["HARVESTER"] || 0;
                const haulerCount = colony.counts["HAULER"] || 0;
                if (harvesterCount < 2 || haulerCount < 1) {
                    const homeEconomyPenalty = 0.1;
                    this.addFactor(factors, "homeEconomyWeak", 1, 1.0, homeEconomyPenalty - 1);
                    return homeEconomyPenalty;
                }
                return 1.0;
            }
            default:
                return 1.0;
        }
    }
    // ==========================================================================
    // HELPERS
    // ==========================================================================
    computeDeficitContribution(deficit, weight) {
        if (deficit <= 0)
            return -0.5 * weight; // Surplus = negative contribution
        return Math.min(deficit, 3) / 3 * weight; // Cap at 3 deficit
    }
}

/**
 * ConstructionEvaluator - Utility-based structure placement decisions
 *
 * Replaces the priority-based logic in placeStructures.ts with factor-based scoring.
 * Every structure type gets a score based on weighted factors.
 *
 * Key differences from old system:
 * - Instead of fixed priority order, scores determine what to build
 * - RCL requirements are soft penalties, not hard gates
 * - Economy health affects non-essential structures
 * - Dependencies are factors, not gates (e.g., terminal without storage gets penalized)
 *
 * Note: Extensions, Containers, and Roads are still handled by their specialized
 * planners (ExtensionPlanner, ContainerPlanner, SmartRoadPlanner). This evaluator
 * focuses on: Spawn, Tower, Storage, Link, Terminal, Extractor, Lab
 */
// ============================================================================
// TYPES
// ============================================================================
// Structure types handled by this evaluator (not by specialized planners)
const EVALUATED_STRUCTURES = [
    STRUCTURE_SPAWN,
    STRUCTURE_TOWER,
    STRUCTURE_STORAGE,
    STRUCTURE_LINK,
    STRUCTURE_TERMINAL,
    STRUCTURE_EXTRACTOR,
    STRUCTURE_LAB,
];
// ============================================================================
// CONSTRUCTION EVALUATOR
// ============================================================================
class ConstructionEvaluator extends BaseEvaluator {
    constructor() {
        super(...arguments);
        this.domain = "construction";
    }
    evaluate(state, colony) {
        const options = [];
        const w = state.weights.construction;
        // Don't evaluate construction during pioneer phase - focus on bootstrapping
        if (this.isPioneerPhase(colony))
            return options;
        // Pre-compute common metrics
        const economyHealth = this.computeEconomyHealth(colony);
        for (const structureType of EVALUATED_STRUCTURES) {
            const option = this.evaluateStructureType(structureType, colony, state, economyHealth, w);
            if (option)
                options.push(option);
        }
        // Sort by score descending
        options.sort((a, b) => b.score - a.score);
        this.logEvaluation(colony.roomName, options);
        return options;
    }
    // ==========================================================================
    // STRUCTURE EVALUATION
    // ==========================================================================
    evaluateStructureType(structureType, colony, state, economyHealth, w) {
        const rcl = colony.rcl;
        // Get max allowed at this RCL
        const maxAllowed = CONTROLLER_STRUCTURES[structureType][rcl] || 0;
        if (maxAllowed === 0)
            return null;
        // Count existing + sites
        const existing = colony.structureCounts[structureType] || 0;
        const sites = colony.siteCounts[structureType] || 0;
        const total = existing + sites;
        // No deficit = no option
        const deficit = maxAllowed - total;
        if (deficit <= 0)
            return null;
        // Get type configuration
        const typeConfig = w.types[structureType];
        if (!typeConfig)
            return null;
        // Start with base priority
        const basePriority = w.basePriority[structureType] || 0;
        let score = basePriority;
        const factors = {};
        // === FACTOR: Deficit ===
        // More deficit = higher score
        const deficitContribution = Math.min(deficit, 3) / 3 * w.factors.completionGap;
        this.addFactor(factors, "deficit", deficit, w.factors.completionGap, deficitContribution);
        score *= 1 + deficitContribution;
        // === FACTOR: RCL Appropriateness ===
        // Soft penalty when below recommended RCL
        const rclDelta = rcl - typeConfig.minRcl;
        const rclFactor = rclDelta >= 0 ? 1.0 : typeConfig.rclPenalty;
        this.addFactor(factors, "rcl", rcl, w.factors.rclProgress, rclFactor - 1);
        score *= rclFactor;
        // === FACTOR: Economy Health ===
        // Low economy penalizes non-essential structures
        const isEssential = this.isEssentialStructure(structureType);
        const econFactor = isEssential ? Math.max(economyHealth, 0.7) : economyHealth;
        this.addFactor(factors, "economy", economyHealth, w.factors.economyImpact, econFactor - 1);
        score *= econFactor;
        // === FACTOR: Storage Requirement ===
        // Some structures need storage first
        if (typeConfig.requiresStorage && !colony.hasStorage) {
            const noStoragePenalty = typeConfig.noStoragePenalty;
            this.addFactor(factors, "noStorage", 1, 1.0, noStoragePenalty - 1);
            score *= noStoragePenalty;
        }
        // === FACTOR: Dependencies ===
        const dependencyFactor = this.computeDependencyFactor(structureType, colony, factors);
        score *= dependencyFactor;
        // === FACTOR: Strategic Value ===
        const strategicFactor = this.computeStrategicFactor(structureType, colony, state, factors);
        score *= strategicFactor;
        // === FACTOR: Concurrent Sites ===
        // Penalize if already have max concurrent sites of this type
        if (sites >= typeConfig.maxConcurrentSites) {
            score = 0;
        }
        if (score <= 1)
            return null;
        return this.createOption({
            type: "build",
            structureType,
            colony: colony.roomName,
        }, `Build ${structureType} (${total}/${maxAllowed})`, score, factors);
    }
    // ==========================================================================
    // FACTOR COMPUTATION
    // ==========================================================================
    isPioneerPhase(colony) {
        if (colony.hasStorage)
            return false;
        if (colony.rcl >= 2)
            return false;
        return !colony.milestones.hasSourceContainers;
    }
    computeEconomyHealth(colony) {
        if (colony.harvestIncome === 0)
            return 0.3;
        if (colony.netFlow >= 0)
            return 1.0;
        return Math.max(0.2, 1 + colony.netFlow / colony.harvestIncome);
    }
    isEssentialStructure(type) {
        // Essential structures are always needed for colony function
        return type === STRUCTURE_SPAWN || type === STRUCTURE_TOWER || type === STRUCTURE_STORAGE;
    }
    computeDependencyFactor(type, colony, factors) {
        switch (type) {
            case STRUCTURE_TERMINAL: {
                // Terminal without storage is much less useful
                if (!colony.hasStorage) {
                    const penalty = 0.1;
                    this.addFactor(factors, "needsStorage", 1, 1.0, penalty - 1);
                    return penalty;
                }
                // Bonus if storage is well-stocked
                if (colony.energyStored > 50000) {
                    const bonus = 1.3;
                    this.addFactor(factors, "storageReady", colony.energyStored, 1.0, bonus - 1);
                    return bonus;
                }
                return 1.0;
            }
            case STRUCTURE_LAB: {
                // Labs need terminal for minerals
                if (!colony.hasTerminal) {
                    const penalty = 0.2;
                    this.addFactor(factors, "needsTerminal", 1, 1.0, penalty - 1);
                    return penalty;
                }
                return 1.0;
            }
            case STRUCTURE_EXTRACTOR: {
                // Extractor without storage/terminal is less useful
                if (!colony.hasStorage) {
                    const penalty = 0.3;
                    this.addFactor(factors, "needsStorage", 1, 1.0, penalty - 1);
                    return penalty;
                }
                return 1.0;
            }
            case STRUCTURE_LINK: {
                // First link should go to controller
                // Second link should go near storage
                const linkCount = colony.linkCount;
                if (linkCount === 0) {
                    // First link: boost if controller doesn't have link
                    if (!colony.milestones.hasControllerLink) {
                        const bonus = 1.5;
                        this.addFactor(factors, "controllerLinkNeeded", 1, 1.0, bonus - 1);
                        return bonus;
                    }
                }
                else if (linkCount === 1) {
                    // Second link: boost if storage doesn't have link
                    if (colony.hasStorage && !colony.milestones.hasStorageLink) {
                        const bonus = 1.4;
                        this.addFactor(factors, "storageLinkNeeded", 1, 1.0, bonus - 1);
                        return bonus;
                    }
                }
                return 1.0;
            }
            default:
                return 1.0;
        }
    }
    computeStrategicFactor(type, colony, state, factors) {
        switch (type) {
            case STRUCTURE_TOWER: {
                // Boost tower priority if under threat
                if (colony.hostileCount > 0) {
                    const threatBoost = 1 + Math.min(colony.hostileDPS * 0.02, 1.5);
                    this.addFactor(factors, "threat", colony.hostileDPS, 1.0, threatBoost - 1);
                    return threatBoost;
                }
                // Boost if we don't have any towers yet (critical defense)
                if (colony.towerCount === 0 && colony.rcl >= 3) {
                    const firstTowerBoost = 1.5;
                    this.addFactor(factors, "firstTower", 1, 1.0, firstTowerBoost - 1);
                    return firstTowerBoost;
                }
                return 1.0;
            }
            case STRUCTURE_STORAGE: {
                // Storage is critical at RCL 4 - major economy upgrade
                if (colony.rcl >= 4 && !colony.hasStorage) {
                    const criticalBoost = 2.0;
                    this.addFactor(factors, "rcl4Storage", 1, 1.0, criticalBoost - 1);
                    return criticalBoost;
                }
                return 1.0;
            }
            case STRUCTURE_SPAWN: {
                // Additional spawns are critical for large colonies
                const spawnCount = colony.structureCounts[STRUCTURE_SPAWN] || 0;
                if (spawnCount === 1 && colony.rcl >= 7) {
                    // Need second spawn at RCL 7
                    const boost = 1.5;
                    this.addFactor(factors, "needMoreSpawns", 1, 1.0, boost - 1);
                    return boost;
                }
                return 1.0;
            }
            case STRUCTURE_LINK: {
                // Links are strategic for energy distribution
                // Boost when economy is strong and we're producing excess
                if (colony.energyStored > 100000 && colony.linkCount < colony.maxLinks) {
                    const boost = 1.2;
                    this.addFactor(factors, "excessEnergy", colony.energyStored, 1.0, boost - 1);
                    return boost;
                }
                return 1.0;
            }
            default:
                return 1.0;
        }
    }
}

/**
 * RemoteMiningEvaluator - Utility-based remote mining decisions
 *
 * Replaces manual addRemote()/removeRemote() calls with automated decisions.
 * Every potential remote room gets a score based on weighted factors.
 *
 * Key features:
 * - Evaluates existing remotes for deactivation/pause
 * - Evaluates potential remotes (from intel) for activation
 * - Factors: distance, source count, safety, profitability, colony capacity
 * - Respects maxActive limit from WeightTable
 *
 * Note: This evaluator produces RemoteAction options. The Arbitrator decides
 * which actions to execute based on scores and constraints.
 */
// ============================================================================
// REMOTE MINING EVALUATOR
// ============================================================================
class RemoteMiningEvaluator extends BaseEvaluator {
    constructor() {
        super(...arguments);
        this.domain = "remotes";
    }
    evaluate(state, colony) {
        const options = [];
        const w = state.weights.remotes;
        // Don't evaluate remotes in early game
        if (colony.rcl < 3)
            return options;
        // Don't evaluate if economy is struggling
        const economyHealth = this.computeEconomyHealth(colony);
        if (economyHealth < 0.5)
            return options;
        // Evaluate existing remotes for pause/deactivate
        for (const remote of colony.remotes) {
            // Check for pause (hostile present)
            if (remote.active && !remote.paused && remote.hostilePresent) {
                const pauseOption = this.evaluatePause(remote, colony, state, w);
                if (pauseOption)
                    options.push(pauseOption);
            }
            // Check for deactivation (underperforming)
            if (remote.active && !remote.paused) {
                const deactivateOption = this.evaluateDeactivate(remote, colony, state, economyHealth, w);
                if (deactivateOption)
                    options.push(deactivateOption);
            }
        }
        // Evaluate potential new remotes from intel
        const potentialRemotes = this.findPotentialRemotes(colony, state);
        for (const intel of potentialRemotes) {
            const activateOption = this.evaluateActivate(intel, colony, state, economyHealth, w);
            if (activateOption)
                options.push(activateOption);
        }
        // Sort by score descending
        options.sort((a, b) => b.score - a.score);
        this.logEvaluation(colony.roomName, options);
        return options;
    }
    // ==========================================================================
    // PAUSE EVALUATION
    // ==========================================================================
    evaluatePause(remote, colony, state, w) {
        // High score for pausing when hostiles present
        const factors = {};
        let score = 80; // Base high score for safety
        // Boost for immediate threat
        const threatBoost = 1.5;
        this.addFactor(factors, "hostileThreat", 1, w.factors.safety, threatBoost - 1);
        score *= threatBoost;
        return this.createOption({
            type: "pause_remote",
            room: remote.roomName,
            colony: colony.roomName,
            reason: "Hostile detected",
        }, `Pause ${remote.roomName} (hostile)`, score, factors);
    }
    // ==========================================================================
    // DEACTIVATE EVALUATION
    // ==========================================================================
    evaluateDeactivate(remote, colony, state, economyHealth, w) {
        const factors = {};
        let score = 10; // Base low score - we don't want to deactivate easily
        // Factor: Profitability
        // Estimate profit = income - hauler cost
        const estimatedProfit = this.estimateProfit(remote, colony);
        if (estimatedProfit <= 0) {
            // Unprofitable - boost deactivation score
            const unprofitablePenalty = 3.0;
            this.addFactor(factors, "unprofitable", estimatedProfit, w.factors.profitability, unprofitablePenalty - 1);
            score *= unprofitablePenalty;
        }
        else {
            // Profitable - reduce deactivation score significantly
            const profitFactor = 0.1;
            this.addFactor(factors, "profitable", estimatedProfit, w.factors.profitability, profitFactor - 1);
            score *= profitFactor;
        }
        // Factor: Distance penalty for far remotes
        if (remote.distance >= 2) {
            const distancePenalty = 1 + remote.distance * 0.3;
            this.addFactor(factors, "distance", remote.distance, Math.abs(w.factors.distance), distancePenalty - 1);
            score *= distancePenalty;
        }
        // Factor: Economy stress - deactivate far remotes when economy is struggling
        if (economyHealth < 0.7 && remote.distance >= 2) {
            const economyPressure = 2.0;
            this.addFactor(factors, "economyPressure", economyHealth, 1.0, economyPressure - 1);
            score *= economyPressure;
        }
        // Factor: Over capacity - deactivate if we have too many active remotes
        const activeCount = colony.activeRemoteCount;
        const maxActive = state.weights.remotes.maxActive;
        if (activeCount > maxActive) {
            const overCapacity = 2.5;
            this.addFactor(factors, "overCapacity", activeCount - maxActive, 1.0, overCapacity - 1);
            score *= overCapacity;
        }
        // Only suggest deactivation if score is high enough
        if (score < 20)
            return null;
        return this.createOption({
            type: "deactivate_remote",
            room: remote.roomName,
            colony: colony.roomName,
            reason: "Underperforming",
        }, `Deactivate ${remote.roomName} (score: ${score.toFixed(1)})`, score, factors);
    }
    // ==========================================================================
    // ACTIVATE EVALUATION
    // ==========================================================================
    evaluateActivate(intel, colony, state, economyHealth, w) {
        const factors = {};
        // Base priority from weights
        let score = 30;
        // Check if already at max active
        const activeCount = colony.activeRemoteCount;
        const maxActive = state.weights.remotes.maxActive;
        if (activeCount >= maxActive) {
            return null; // Don't activate if at capacity
        }
        // Factor: Source count (more = better)
        const sourceBonus = 1 + (intel.sources - 1) * w.factors.sourceCount * 0.5;
        this.addFactor(factors, "sources", intel.sources, w.factors.sourceCount, sourceBonus - 1);
        score *= sourceBonus;
        // Factor: Distance (closer = better)
        const distance = intel.distanceFromHome;
        const distancePenalty = Math.max(0.3, 1 + distance * w.factors.distance * 0.3);
        this.addFactor(factors, "distance", distance, Math.abs(w.factors.distance), distancePenalty - 1);
        score *= distancePenalty;
        // Factor: Minimum sources by distance
        const minSources = w.minSources[distance] || 1;
        if (intel.sources < minSources) {
            // Not enough sources for this distance - heavy penalty
            const insufficientSources = 0.1;
            this.addFactor(factors, "insufficientSources", intel.sources, 1.0, insufficientSources - 1);
            score *= insufficientSources;
        }
        // Factor: Safety (no hostiles = better)
        if (intel.hostile || intel.invaderCore) {
            const safetyPenalty = 0.2;
            this.addFactor(factors, "hostile", intel.hostileCount, w.factors.safety, safetyPenalty - 1);
            score *= safetyPenalty;
        }
        else {
            const safetyBonus = 1.2;
            this.addFactor(factors, "safe", 0, w.factors.safety, safetyBonus - 1);
            score *= safetyBonus;
        }
        // Factor: Economy health - only activate when economy is strong
        if (economyHealth < 0.8) {
            const economyPenalty = economyHealth;
            this.addFactor(factors, "economy", economyHealth, 1.0, economyPenalty - 1);
            score *= economyPenalty;
        }
        // Factor: Colony capacity (RCL determines how many remotes we can handle)
        const rclCapacity = this.getRclCapacity(colony.rcl);
        if (activeCount >= rclCapacity) {
            // At capacity for this RCL
            const capacityPenalty = 0.1;
            this.addFactor(factors, "rclCapacity", activeCount, 1.0, capacityPenalty - 1);
            score *= capacityPenalty;
        }
        // Factor: Storage requirement for distance 2+
        if (distance >= 2 && !colony.hasStorage) {
            const noStoragePenalty = 0.2;
            this.addFactor(factors, "noStorage", 1, 1.0, noStoragePenalty - 1);
            score *= noStoragePenalty;
        }
        // Only suggest activation if score is high enough
        if (score < 30)
            return null;
        return this.createOption({
            type: "activate_remote",
            room: intel.roomName,
            colony: colony.roomName,
            distance: distance,
        }, `Activate ${intel.roomName} (${intel.sources} src, dist ${distance})`, score, factors);
    }
    // ==========================================================================
    // HELPER METHODS
    // ==========================================================================
    computeEconomyHealth(colony) {
        if (colony.harvestIncome === 0)
            return 0.3;
        if (colony.netFlow >= 0)
            return 1.0;
        return Math.max(0.2, 1 + colony.netFlow / colony.harvestIncome);
    }
    estimateProfit(remote, colony) {
        // Estimate income: sources * 10 energy/tick
        const income = remote.sources * 10;
        // Estimate hauler cost: based on distance and carry capacity
        // Rough estimate: more distance = more haulers needed
        const haulerCost = remote.distance * 2; // Energy equivalent per tick
        return income - haulerCost;
    }
    getRclCapacity(rcl) {
        // How many active remotes can we handle at each RCL?
        if (rcl <= 2)
            return 0;
        if (rcl === 3)
            return 1;
        if (rcl === 4)
            return 2;
        if (rcl === 5)
            return 3;
        if (rcl === 6)
            return 4;
        if (rcl >= 7)
            return 5;
        return 0;
    }
    findPotentialRemotes(colony, state) {
        const potentials = [];
        const existingRemotes = new Set(colony.remotes.map((r) => r.roomName));
        // Check intel for nearby rooms that could be remotes
        for (const [roomName, intel] of state.intel) {
            // Skip if already a remote
            if (existingRemotes.has(roomName))
                continue;
            // Skip owned rooms
            if (intel.owner)
                continue;
            // Skip source keeper rooms
            if (intel.roomType === "sourceKeeper")
                continue;
            // Skip center/highway rooms
            if (intel.roomType !== "normal")
                continue;
            // Skip if no sources
            if (intel.sources === 0)
                continue;
            // Skip if too far (distance > 2)
            if (intel.distanceFromHome > 2)
                continue;
            // Skip if stale intel (older than 10000 ticks)
            if (Game.time - intel.lastScanned > 10000)
                continue;
            potentials.push(intel);
        }
        // Sort by distance, then sources
        potentials.sort((a, b) => {
            if (a.distanceFromHome !== b.distanceFromHome) {
                return a.distanceFromHome - b.distanceFromHome;
            }
            return b.sources - a.sources;
        });
        return potentials;
    }
}

/**
 * MilitaryEvaluator - Utility-based military decisions
 *
 * Replaces manual military.attack() calls with automated decisions.
 * Evaluates attack opportunities and defense needs with weighted factors.
