    if (controller && !controllerHasLink) {
        return findControllerLinkPosition(room, controller, terrain);
    }
    // Second priority: Storage link (on hauler path)
    if (storage && spawn) {
        // Check if storage already has a link nearby
        const storageHasLink = existingLinks.some((l) => l.pos.getRangeTo(storage) <= 3);
        if (!storageHasLink) {
            return findStorageLinkPosition(room, storage, spawn, terrain);
        }
    }
    // Third+ priority: Source links (near sources for direct harvester deposit)
    var sources = room.find(FIND_SOURCES);
    for (var i = 0; i < sources.length; i++) {
        var source = sources[i];
        // Check if this source already has a link nearby (range 2)
        var sourceHasLink = existingLinks.some(function (l) {
            return l.pos.getRangeTo(source) <= 2;
        });
        // Also check construction sites
        var sourceHasLinkSite = room.find(FIND_CONSTRUCTION_SITES, {
            filter: function (s) {
                return (s.structureType === STRUCTURE_LINK && s.pos.getRangeTo(source) <= 2);
            },
        }).length > 0;
        if (!sourceHasLink && !sourceHasLinkSite) {
            return findSourceLinkPosition(room, source, terrain);
        }
    }
    // Fallback: near spawn (for any additional links beyond sources)
    return findNearSpawnPosition(room, spawnPos, terrain);
}
/**
 * Find position for controller link - near controller for upgraders
 */
function findControllerLinkPosition(room, controller, terrain) {
    const candidates = [];
    // Search in range 2-4 of controller (upgraders work at range 3)
    for (let dx = -4; dx <= 4; dx++) {
        for (let dy = -4; dy <= 4; dy++) {
            const x = controller.pos.x + dx;
            const y = controller.pos.y + dy;
            const range = Math.max(Math.abs(dx), Math.abs(dy));
            if (range < 2 || range > 4)
                continue;
            if (!isValidBuildPos(room, x, y, terrain))
                continue;
            // Prefer range 2-3 (closer to upgraders)
            let score = range === 2 ? 0 : range === 3 ? 1 : 2;
            // Bonus for being on a road (existing infrastructure)
            const hasRoad = room
                .lookForAt(LOOK_STRUCTURES, x, y)
                .some((s) => s.structureType === STRUCTURE_ROAD);
            if (hasRoad)
                score -= 1;
            // Bonus for plain terrain
            if (terrain.get(x, y) === 0)
                score -= 0.5;
            candidates.push({ x, y, score });
        }
    }
    candidates.sort((a, b) => a.score - b.score);
    return candidates[0] || null;
