            if (range === 1) {
                score += 10;
            }
            // Big bonus for being adjacent to container (harvester can transfer without moving)
            if (container) {
                var pos = new RoomPosition(x, y, room.name);
                if (pos.isNearTo(container)) {
                    score += 20;
                }
